input.command:
D=$(mktemp -d) && cat > $D/stub.mjs <<'EOF'
const sites = {
  'https://brand994.example/': '<html><head><link rel="icon" href="/fav.png"></head>',
  'https://brand995.example/': '<html><head><title>no icon</title></head>',
};
let calls = 0;
globalThis.fetch = async (u) => { calls++; console.error('FETCH', u, calls);
  if (u === 'https://brand996.example/') throw new Error('down');
  return Object.assign(new Response(sites[u] ?? '', { status: sites[u] ? 200 : 404 }), {}); };
EOF
cd /tmp/logs/start-1 && (node --import $D/stub.mjs src/server.js 2>$D/err & echo $! > $D/pid) && until curl -s localhost:3000/brands >/dev/null; do :; done
for d in brand994.example brand994.example brand995.example brand996.example brand996.example brand930.example brand1.example evil.internal; do printf '%s -> ' $d; curl -s -o /dev/null -w '%{http_code} %{redirect_url}\n' "localhost:3000/logo?domain=$d"; done
kill $(cat $D/pid); cat $D/err

D=$(mktemp -d) && cat > $D/stub.mjs <<'EOF'
const sites = {
  'https://brand994.example/': '<html><head><link rel="icon" href="/fav.png"></head>',
  'https://brand995.example/': '<html><head><title>no icon</title></head>',
};
let calls = 0;
globalThis.fetch = async (u) => { console.error('FETCH', u, ++calls);
  if (u === 'https://brand996.example/') throw new Error('down');
  const r = new Response(sites[u] ?? '', { status: sites[u] ? 200 : 404 });
  Object.defineProperty(r, 'url', { value: u }); return r; };
EOF
cd /tmp/logs/start-1 && (node --import $D/stub.mjs src/server.js 2>$D/err & echo $! > $D/pid) && until curl -s 'http://[::1]:3000/brands' >/dev/null; do :; done
for d in brand994.example brand994.example brand995.example brand996.example brand996.example brand997.example brand930.example brand1.example evil.internal; do printf '%s -> ' $d; curl -s -o /dev/null -w '%{http_code} %{redirect_url}\n' "http://[::1]:3000/logo?domain=$d"; done
kill $(cat $D/pid); cat $D/err
